#!/data/data/com.termux/files/usr/bin/bash
# ============================================================================
# MausBot 一次性自举脚本（由 App 自动生成并复制，用户只需粘贴回车一次）
# 全程自动：开 Termux 外部调用 -> 装 Node/服务 -> 写安卓补丁 -> 启动
# 之后由 App 自动拉起服务，永远不用再碰命令行。
# ============================================================================
set -u
BASE="$HOME/.openmausbot"
mkdir -p "$BASE" "$HOME/.termux"
say(){ echo; echo "==> $*"; }

say "[1/5] 开启「允许 App 自动启动」（安卓规定，只需这一次）"
grep -q '^allow-external-apps' "$HOME/.termux/termux.properties" 2>/dev/null \
  || echo 'allow-external-apps = true' >> "$HOME/.termux/termux.properties"

say "[2/5] 安装运行环境（首次约几分钟，屏幕会滚动，别急）"
apt update -y >/dev/null 2>&1 || true
apt full-upgrade -y -o Dpkg::Options::=--force-confdef -o Dpkg::Options::=--force-confold >/dev/null 2>&1 || true
pkg install -y nodejs-lts curl termux-api >/dev/null 2>&1 || { echo "!! 装 Node 失败，请检查网络后重新粘贴一次"; exit 1; }
echo "node: $(node -v 2>/dev/null)"

say "[3/5] 安装 openmausbot"
npm install -g openmausbot >/dev/null 2>&1 || { echo "!! 安装失败，请检查网络后重新粘贴一次"; exit 1; }

say "[4/5] 写入安卓专用补丁"
echo ''  | base64 -d > "$BASE/omb-shim.cjs"
echo '' | base64 -d > "$BASE/patch-dist.mjs"
echo '' | base64 -d > "$BASE/start-omb.sh"
echo ''  | base64 -d > "$BASE/config.template.json"
# 只在首次生成 config.json，绝不覆盖用户已经填好的模型 / 密钥配置
[ -f "$BASE/config.json" ] || cp "$BASE/config.template.json" "$BASE/config.json"
chmod 600 "$BASE/config.json" 2>/dev/null || true
chmod +x "$BASE/start-omb.sh" 2>/dev/null || true
# 定位 dist-server 做第二道保险补丁。$PREFIX 在 Termux 登录 shell 里必有，
# 但用户可能粘贴到非登录 shell；set -u 下直接引用会中断整个脚本，故一律用默认值兜底。
# 这一步是可选增强（运行时 shim 已足够），任何失败都不得阻断后面的启动。
DIST=""
for c in "${PREFIX:-}/lib/node_modules/openmausbot/dist-server" \
         "$(npm root -g 2>/dev/null || true)/openmausbot/dist-server" \
         "$HOME/../usr/lib/node_modules/openmausbot/dist-server"; do
  [ -d "$c" ] && DIST="$c" && break
done
if [ -n "$DIST" ] && [ -f "$BASE/patch-dist.mjs" ]; then
  node "$BASE/patch-dist.mjs" "$DIST" >/dev/null 2>&1 && echo "补丁已应用" || echo "补丁跳过（运行时兼容层已足够）"
else
  echo "补丁跳过（未定位到 dist-server；运行时兼容层已足够）"
fi

say "[5/5] 让配置生效并启动服务"
termux-reload-settings 2>/dev/null || true
am broadcast --user 0 -a com.termux.app.reload_style com.termux >/dev/null 2>&1 || true
termux-wake-lock 2>/dev/null || true
bash "$BASE/start-omb.sh" --once || true

HEALTH=""
for i in $(seq 1 45); do
  HEALTH=$(curl -s --max-time 2 http://127.0.0.1:8799/api/health 2>/dev/null)
  [ -n "$HEALTH" ] && break
  sleep 1
done
echo
if [ -n "$HEALTH" ]; then
  echo "=============================================="
  echo "  装好了，服务已经跑起来 ✓"
  echo "  回到 MausBot，会自动进入聊天界面"
  echo "  以后点开图标就能用，不用再做任何设置"
  echo "=============================================="
else
  echo "服务还在启动中。回到 MausBot 点「重新检测」即可。"
  echo "排查日志： tail -40 $BASE/serve.log"
fi
